import React, { useEffect, useState } from "react";
import axios from "axios";

const API_URL = "http://localhost:5000";

function VotingPage({ auth }) {
  const [candidates, setCandidates] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchCandidates = async () => {
      try {
        const res = await axios.get(`${API_URL}/api/candidates`);
        setCandidates(res.data);
      } catch (error) {
        console.error("Failed to fetch candidates");
      } finally {
        setLoading(false);
      }
    };

    fetchCandidates();
  }, []);

  const handleVote = async (candidateId) => {
    const confirmVote = window.confirm(
      "Are you sure you want to vote for this candidate? This cannot be changed."
    );

    if (!confirmVote) return;

    try {
      await axios.post(
        `${API_URL}/api/votes`,
        { candidateId },
        { headers: { Authorization: `Bearer ${auth.token}` } }
      );

      alert("✅ Vote cast successfully!");
    } catch {
      alert("❌ Vote failed or you already voted.");
    }
  };

  // Group candidates by position
  const groupedCandidates = candidates.reduce((groups, c) => {
    if (!groups[c.candidacy]) groups[c.candidacy] = [];
    groups[c.candidacy].push(c);
    return groups;
  }, {});

  if (loading) return <h2 style={{ padding: 20 }}>Loading candidates...</h2>;

  return (
    <div style={{ padding: 40, maxWidth: 1200, margin: "auto" }}>
      <h1 style={{ textAlign: "center", marginBottom: 40 }}>
        Student Election 2026
      </h1>

      {Object.entries(groupedCandidates).map(([position, list]) => (
        <div key={position} style={{ marginBottom: 50 }}>
          <h2 style={{ marginBottom: 20 }}>{position}</h2>

          <div
            style={{
              display: "flex",
              flexWrap: "wrap",
              gap: 25,
            }}
          >
            {list.map((candidate) => (
              <div
                key={candidate._id}
                style={{
                  width: 300,
                  backgroundColor: "#ffffff",
                  borderRadius: 15,
                  padding: 20,
                  boxShadow: "0 8px 20px rgba(0,0,0,0.08)",
                  transition: "0.3s ease",
                }}
              >
                {/* Candidate Image */}
                {candidate.image && (
                  <img
                    src={`http://localhost:5000/${candidate.image}`}
                    alt="candidate"
                    style={{
                      width: "100%",
                      height: 200,
                      objectFit: "cover",
                      borderRadius: 10,
                      marginBottom: 15,
                    }}
                  />
                )}

                {/* Candidate Info */}
                <h3 style={{ marginBottom: 5 }}>
                  {candidate.firstName} {candidate.lastName}
                </h3>

                <p style={{ margin: "5px 0", fontSize: 14 }}>
                  🎓 {candidate.yearLevel} - {candidate.block}
                </p>

                <p
                  style={{
                    fontSize: 14,
                    marginTop: 10,
                    minHeight: 60,
                  }}
                >
                  {candidate.description}
                </p>

                {/* Vote Button */}
                <button
                  onClick={() => handleVote(candidate._id)}
                  style={{
                    marginTop: 15,
                    padding: "10px",
                    width: "100%",
                    backgroundColor: "#6366f1",
                    color: "#fff",
                    border: "none",
                    borderRadius: 8,
                    fontWeight: "600",
                    cursor: "pointer",
                  }}
                >
                  Vote
                </button>
              </div>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
}

export default VotingPage;
